SELECT json_build_object('check','daily_month_exact_decimal','scope','new_contract','errors',(SELECT count(*) FROM (SELECT source_month_id,sum(oil_legacy_quantity) o,sum(gas_legacy_quantity) g,sum(water_legacy_quantity) w FROM dds.fact_production_day GROUP BY 1)d JOIN ods.sng_tbl_production_volume p ON p.id=d.source_month_id WHERE d.o<>round(p.oil_volume::numeric,6) OR d.g<>round(p.gas_volume::numeric,6) OR d.w<>round(p.water_volume::numeric,6)));
SELECT json_build_object('check','daily_source_double_tolerance','scope','new_contract','errors',(SELECT count(*) FROM (SELECT source_month_id,sum(oil_legacy_quantity) o,sum(gas_legacy_quantity) g,sum(water_legacy_quantity) w FROM dds.fact_production_day GROUP BY 1)d JOIN ods.sng_tbl_production_volume p ON p.id=d.source_month_id WHERE abs(d.o::double precision-p.oil_volume)>0.000001+1e-12*abs(p.oil_volume) OR abs(d.g::double precision-p.gas_volume)>0.000001+1e-12*abs(p.gas_volume) OR abs(d.w::double precision-p.water_volume)>0.000001+1e-12*abs(p.water_volume)));
SELECT json_build_object('check','scd_overlap','scope','new_contract','errors',(SELECT count(*) FROM dds.dim_well_scd2 a JOIN dds.dim_well_scd2 b ON a.well_id=b.well_id AND a.well_sk<b.well_sk AND a.valid_from<b.valid_to AND b.valid_from<a.valid_to));
SELECT json_build_object('check','scd_fact_one_version','scope','new_contract','errors',(SELECT count(*) FROM (SELECT p.well_id,p.business_date FROM dds.fact_production_day p LEFT JOIN dds.dim_well_scd2 s ON s.well_id=p.well_id AND p.business_date>=s.valid_from AND p.business_date<s.valid_to GROUP BY 1,2 HAVING count(s.well_sk)<>1)d));
SELECT json_build_object('check','downtime_overlap','scope','new_contract','errors',(SELECT count(*) FROM dds.fact_downtime_interval a JOIN dds.fact_downtime_interval b ON a.well_id=b.well_id AND a.downtime_id<b.downtime_id AND a.starts_at<b.ends_at AND b.starts_at<a.ends_at));
SELECT json_build_object('check','hours_bounds','scope','new_contract','errors',(SELECT count(*) FROM dds.fact_production_day WHERE operating_hours<0 OR operating_hours>24));
SELECT json_build_object('check','energy_price','scope','new_contract','errors',(SELECT count(*) FROM dds.fact_energy_day e JOIN ref.energy_tariff t ON t.tariff_id=e.tariff_id WHERE e.energy_kwh<0 OR e.energy_cost_rub<>round(e.energy_kwh*t.rub_per_kwh,2)));
SELECT json_build_object('check','zero_denominator_null','scope','new_contract','errors',(SELECT count(*) FROM dm.energy_intensity_day WHERE (oil_legacy_quantity=0 AND kwh_per_legacy_unit IS NOT NULL) OR (oil_legacy_quantity<>0 AND kwh_per_legacy_unit IS NULL)));
SELECT json_build_object('check','plan_daily_month_conservation','scope','new_contract','errors',(SELECT count(*) FROM (SELECT well_id,date_trunc('month',business_date)::date m,sum(plan_oil_legacy) x FROM dm.well_day_balance GROUP BY 1,2)d JOIN dds.fact_production_plan_month p ON p.well_id=d.well_id AND p.month_start=d.m AND p.scenario='base' WHERE d.x<>p.oil_plan_legacy));
SELECT json_build_object('check','shipment_mass_balance','scope','new_contract','errors',(SELECT count(*) FROM dm.shipment_balance_month WHERE opening_m3+received_synthetic_m3-dispatched_m3<>closing_m3 OR closing_m3<0));
SELECT json_build_object('check','shipment_month_continuity','scope','new_contract','errors',(SELECT count(*) FROM (SELECT *,lag(closing_m3) OVER(PARTITION BY locality_id,product_id ORDER BY month_start) prev FROM dm.shipment_balance_month)d WHERE prev IS NOT NULL AND prev<>opening_m3));
SELECT json_build_object('check','quality_flags_correct','scope','new_contract','errors',(SELECT count(*) FROM dds.fact_quality_measurement m JOIN ref.quality_spec s ON s.spec_id=m.spec_id WHERE m.is_compliant IS DISTINCT FROM (m.measured_value>=s.min_value AND m.measured_value<=s.max_value)));
SELECT json_build_object('check','mart_aggregate_parity','scope','new_contract','errors',(SELECT count(*) FROM (SELECT w.fieldid locality_id,date_trunc('month',p.prod_date)::date month_start,sum(round(p.oil_volume::numeric,6)) oil FROM ods.sng_tbl_production_volume p JOIN ods.sng_tbl_well w ON w.id=p.well_id GROUP BY 1,2)s FULL OUTER JOIN dm.field_month_performance t USING(locality_id,month_start) WHERE s.oil IS DISTINCT FROM t.oil_actual_legacy));
SELECT json_build_object('check','default_partitions_empty','scope','new_contract','errors',(SELECT count(*) FROM dds.fact_production_day WHERE business_date<DATE '2025-01-01' OR business_date>=DATE '2026-01-01'));
SELECT json_build_object('check','telemetry_utc_range','scope','new_contract','errors',(SELECT count(*) FROM dds.fact_telemetry_hour WHERE event_ts<TIMESTAMP '2025-01-01' OR event_ts>=TIMESTAMP '2026-01-01'));
SELECT json_build_object('check','raw_telemetry_count','scope','new_contract','errors',(SELECT abs((SELECT count(*) FROM stg.measurement_event)-(SELECT count(*) FROM dds.fact_telemetry_hour))));
SELECT json_build_object('check','raw_json_parse','scope','new_contract','errors',(SELECT count(*) FROM stg.measurement_event WHERE (payload->>'pressure_kpa') IS NULL OR (payload->>'water_cut_pct') IS NULL));
